/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Library: none — pure native Remotion spring/interpolate logic for smooth, continuous, controllable "camera" movement and UI choreography.

const { fontFamily: interFamily } = loadInter();



export type EcosystemSequenceProps = Record<string, any>;

// Timing Constants (Frames at 30fps)
const T_START = 0;
const T_MAIN_IN = 90;
const T_ORBIT_IN = 180;
const T_COUNT_IN = 270;
const T_PAN_RIGHT = 390;
const T_AUDIENCE_IN = 450;
const T_ZOOM_OUT = 510;
const T_TEASE = 630;

const EcosystemSequence: React.FC<EcosystemSequenceProps> = ({
  backgroundColor = "#04383f",
  transparentBackground = false,
  durationInSeconds = 23,
  primaryHighlight = "#81a969",
  secondaryHighlight = "#6b8a62",
  surfaceColor = "#f7f8ef",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const cx = width / 2;
  const cy = height / 2;

  // --- CAMERA LOGIC ---
  const camScale = interpolate(
    frame,
    [T_START, T_MAIN_IN, T_ORBIT_IN, T_PAN_RIGHT, T_PAN_RIGHT + 60, T_ZOOM_OUT, T_ZOOM_OUT + 60],
    [1.0, 1.0, 1.15, 1.15, 1.0, 1.0, 0.75],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.bezier(0.25, 0.1, 0.25, 1) }
  );

  const camX = interpolate(
    frame,
    [T_START, T_PAN_RIGHT, T_PAN_RIGHT + 60, T_ZOOM_OUT, T_ZOOM_OUT + 60],
    [0, 0, -220 * s, -220 * s, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.bezier(0.25, 0.1, 0.25, 1) }
  );

  const camY = interpolate(
    frame,
    [T_START, T_ZOOM_OUT, T_ZOOM_OUT + 60],
    [0, 0, -80 * s],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.bezier(0.25, 0.1, 0.25, 1) }
  );

  // --- BACKGROUND GRID ---
  const gridSpacing = 100 * s;
  const numVLines = Math.ceil(width / gridSpacing) + 4;
  const numHLines = Math.ceil(height / gridSpacing) + 4;

  const gridOffset = (frame * 0.5) % gridSpacing;

  const vLines = useMemo(() => Array.from({ length: numVLines }).map((_, i) => i - 2), [numVLines]);
  const hLines = useMemo(() => Array.from({ length: numHLines }).map((_, i) => i - 2), [numHLines]);

  // --- ANIMATED ELEMENTS ---
  
  // Main Channel
  const mainEnter = spring({ frame: frame - T_MAIN_IN, fps, config: { damping: 14 } });
  const mainOpacity = interpolate(frame, [T_MAIN_IN, T_MAIN_IN + 15], [0, 1], { extrapolateRight: "clamp" });
  const mainDriftY = Math.sin(frame / 60) * 15 * s;
  const mainDriftRot = Math.cos(frame / 70) * 1.5;

  // Orbit & Label
  const orbitReveal = interpolate(frame, [T_ORBIT_IN, T_ORBIT_IN + 45], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  
  // Subscriber Counter
  const countReveal = interpolate(frame, [T_COUNT_IN, T_COUNT_IN + 15], [0, 1], { extrapolateRight: "clamp" });
  const countNum = Math.floor(interpolate(frame, [T_COUNT_IN, T_COUNT_IN + 45], [0, 310], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.quad) }));
  const countPulse = frame > T_COUNT_IN + 45 ? spring({ frame: frame - (T_COUNT_IN + 45), fps, config: { damping: 10 }, from: 1.1, to: 1 }) : 1;

  // Second Channel
  const secondEnter = spring({ frame: frame - T_PAN_RIGHT, fps, config: { damping: 14 } });
  const secondOpacity = interpolate(frame, [T_PAN_RIGHT, T_PAN_RIGHT + 15], [0, 1], { extrapolateRight: "clamp" });
  const secondDriftY = Math.sin((frame + 30) / 60) * 12 * s;

  // Socials
  const socialIn1 = spring({ frame: frame - T_ZOOM_OUT, fps, config: { damping: 12 } });
  const socialIn2 = spring({ frame: frame - (T_ZOOM_OUT + 10), fps, config: { damping: 12 } });
  const socialIn3 = spring({ frame: frame - (T_ZOOM_OUT + 20), fps, config: { damping: 12 } });
  const socialOpacity = interpolate(frame, [T_ZOOM_OUT, T_ZOOM_OUT + 15], [0, 1], { extrapolateRight: "clamp" });

  const socialReduceScale = interpolate(frame, [T_TEASE, T_TEASE + 30], [1, 0.85], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.ease });

  // Connections (flowing dashes)
  const dashOffset = -frame * 3;

  // Base coordinates for nodes (relative to scene center)
  const mainCoords = { x: 0, y: 0 };
  const secondCoords = { x: 500 * s, y: 0 };
  const linkedinCoords = { x: -450 * s, y: 350 * s };
  const igCoords = { x: 0, y: 400 * s };
  const tiktokCoords = { x: 450 * s, y: 350 * s };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily, overflow: "hidden" }}>
      
      {/* Background Grid & Curves */}
      <AbsoluteFill style={{ opacity: 0.15 }}>
        <svg width="100%" height="100%" style={{ transform: `translate(${-gridOffset}px, ${-gridOffset}px)` }}>
          {vLines.map((i) => (
            <line key={`v-${i}`} x1={i * gridSpacing} y1={0} x2={i * gridSpacing} y2={height + gridSpacing * 2} stroke={primaryHighlight} strokeWidth={1 * s} />
          ))}
          {hLines.map((i) => (
            <line key={`h-${i}`} x1={0} y1={i * gridSpacing} x2={width + gridSpacing * 2} y2={i * gridSpacing} stroke={primaryHighlight} strokeWidth={1 * s} />
          ))}
        </svg>
      </AbsoluteFill>
      <AbsoluteFill style={{ opacity: 0.2 }}>
        <svg width="100%" height="100%">
          <path 
            d={`M -100 ${cy} Q ${cx} ${cy - 400 * s} ${width + 100} ${cy + 200 * s}`} 
            fill="none" 
            stroke={primaryHighlight} 
            strokeWidth={3 * s} 
            style={{ transform: `translateY(${Math.sin(frame / 120) * 50 * s}px)` }} 
          />
          <path 
            d={`M -100 ${height - 100 * s} Q ${cx} ${height - 400 * s} ${width + 100} ${height + 100 * s}`} 
            fill="none" 
            stroke={secondaryHighlight} 
            strokeWidth={2 * s} 
            style={{ transform: `translateY(${Math.cos(frame / 100) * -30 * s}px)` }} 
          />
        </svg>
      </AbsoluteFill>

      {/* MASTER CAMERA WRAPPER */}
      <AbsoluteFill
        style={{
          transformOrigin: "center",
          transform: `scale(${camScale}) translate(${camX}px, ${camY}px)`,
        }}
      >
        <AbsoluteFill style={{ left: cx, top: cy, width: 0, height: 0 }}>
          
          {/* CONNECTIONS (SVG layer behind elements) */}
          <svg width={2000 * s} height={2000 * s} style={{ position: "absolute", left: -1000 * s, top: -1000 * s, overflow: "visible" }}>
            <g transform={`translate(${1000 * s}, ${1000 * s})`}>
              
              {/* Central Orbit */}
              {frame >= T_ORBIT_IN && (
                <circle 
                  cx={0} 
                  cy={0} 
                  r={380 * s} 
                  fill="none" 
                  stroke={primaryHighlight} 
                  strokeWidth={2 * s}
                  strokeDasharray={`${2400 * s}`}
                  strokeDashoffset={2400 * s * (1 - orbitReveal)}
                  style={{ transition: "none" }}
                />
              )}

              {/* Main to Second Line */}
              {frame >= T_PAN_RIGHT && (
                <line 
                  x1={mainCoords.x} 
                  y1={mainCoords.y} 
                  x2={secondCoords.x} 
                  y2={secondCoords.y} 
                  stroke={primaryHighlight} 
                  strokeWidth={2 * s} 
                  opacity={secondOpacity * 0.5}
                />
              )}

              {/* To Socials */}
              {frame >= T_ZOOM_OUT && (
                <>
                  <path 
                    d={`M ${mainCoords.x} ${mainCoords.y + 100 * s} Q ${linkedinCoords.x} ${mainCoords.y + 100 * s} ${linkedinCoords.x} ${linkedinCoords.y - 60 * s}`}
                    fill="none" stroke={primaryHighlight} strokeWidth={2 * s} strokeDasharray={`${8 * s} ${8 * s}`} strokeDashoffset={dashOffset}
                    opacity={socialOpacity}
                  />
                  <path 
                    d={`M ${mainCoords.x} ${mainCoords.y + 100 * s} L ${igCoords.x} ${igCoords.y - 60 * s}`}
                    fill="none" stroke={primaryHighlight} strokeWidth={2 * s} strokeDasharray={`${8 * s} ${8 * s}`} strokeDashoffset={dashOffset}
                    opacity={socialOpacity}
                  />
                  <path 
                    d={`M ${mainCoords.x} ${mainCoords.y + 100 * s} Q ${tiktokCoords.x} ${mainCoords.y + 100 * s} ${tiktokCoords.x} ${tiktokCoords.y - 60 * s}`}
                    fill="none" stroke={primaryHighlight} strokeWidth={2 * s} strokeDasharray={`${8 * s} ${8 * s}`} strokeDashoffset={dashOffset}
                    opacity={socialOpacity}
                  />
                </>
              )}

              {/* Tease Paths */}
              {frame >= T_TEASE && (
                <g opacity={interpolate(frame, [T_TEASE, T_TEASE + 30], [0, 0.4])}>
                  <path d={`M ${linkedinCoords.x} ${linkedinCoords.y + 60 * s} Q ${linkedinCoords.x} ${linkedinCoords.y + 200 * s} ${linkedinCoords.x - 100 * s} ${linkedinCoords.y + 250 * s}`} fill="none" stroke={primaryHighlight} strokeWidth={3 * s} strokeDasharray={`${10 * s} ${10 * s}`} strokeDashoffset={-dashOffset} />
                  <path d={`M ${igCoords.x} ${igCoords.y + 100 * s} L ${igCoords.x} ${igCoords.y + 250 * s}`} fill="none" stroke={primaryHighlight} strokeWidth={3 * s} strokeDasharray={`${10 * s} ${10 * s}`} strokeDashoffset={-dashOffset} />
                  <path d={`M ${tiktokCoords.x} ${tiktokCoords.y + 60 * s} Q ${tiktokCoords.x} ${tiktokCoords.y + 200 * s} ${tiktokCoords.x + 100 * s} ${tiktokCoords.y + 250 * s}`} fill="none" stroke={primaryHighlight} strokeWidth={3 * s} strokeDasharray={`${10 * s} ${10 * s}`} strokeDashoffset={-dashOffset} />
                </g>
              )}
            </g>
          </svg>

          {/* AUDIENCE DOTS */}
          {frame >= T_AUDIENCE_IN && frame < T_ZOOM_OUT + 30 && (
            <AbsoluteFill style={{ overflow: "visible" }}>
               {Array.from({ length: 4 }).map((_, i) => {
                 const delay = i * 15;
                 const localF = Math.max(0, frame - T_AUDIENCE_IN - delay);
                 const progress = Math.min(1, localF / 45);
                 if (progress === 0 || progress === 1) return null;
                 const xPos = interpolate(progress, [0, 1], [secondCoords.x + 300 * s, secondCoords.x + 180 * s]);
                 const yPos = secondCoords.y + (i - 1.5) * 40 * s;
                 return (
                   <div key={`dot-${i}`} style={{
                     position: "absolute", left: xPos, top: yPos,
                     width: 24 * s, height: 24 * s,
                     backgroundColor: primaryHighlight, borderRadius: "50%",
                     transform: "translate(-50%, -50%)",
                     opacity: Math.sin(progress * Math.PI)
                   }}>
                     <svg width="100%" height="100%" viewBox="0 0 24 24" fill="none" stroke={surfaceColor} strokeWidth={2}>
                        <circle cx="12" cy="8" r="4" />
                        <path d="M4 20c0-4 4-7 8-7s8 3 8 7" />
                     </svg>
                   </div>
                 );
               })}
            </AbsoluteFill>
          )}

          {/* 310K COUNTER (Positioned above "MAIN YOUTUBE CHANNEL" label) */}
          {frame >= T_COUNT_IN && (
            <div style={{
              position: "absolute",
              left: 0,
              top: -390 * s,
              transform: `translate(-50%, -50%) scale(${countReveal * countPulse}) translateY(${mainDriftY}px)`,
              opacity: countReveal,
              color: surfaceColor,
              display: "flex",
              flexDirection: "column",
              alignItems: "center"
            }}>
              <div style={{ fontSize: 100 * s, fontWeight: 900, lineHeight: 1, letterSpacing: "-0.02em" }}>
                {countNum}K+
              </div>
              <div style={{ 
                fontSize: 22 * s, 
                fontWeight: 600, 
                letterSpacing: "0.2em", 
                color: surfaceColor,
                marginTop: 10 * s,
                paddingBottom: 8 * s,
                borderBottom: `4px solid ${primaryHighlight}`
              }}>
                SUBSCRIBERS
              </div>
            </div>
          )}

          {/* MAIN CHANNEL CARD */}
          {frame >= T_MAIN_IN && (
            <div style={{
              position: "absolute",
              left: mainCoords.x,
              top: mainCoords.y,
              transform: `translate(-50%, -50%) scale(${mainEnter}) translateY(${mainDriftY}px) rotate(${mainDriftRot}deg)`,
              opacity: mainOpacity,
              width: 560 * s,
              height: 380 * s,
            }}>
              
              {/* Orbit Label above card */}
              {frame >= T_ORBIT_IN && (
                <div style={{
                  position: "absolute",
                  top: -80 * s,
                  left: "50%",
                  transform: "translateX(-50%)",
                  backgroundColor: backgroundColor,
                  border: `2px solid ${primaryHighlight}`,
                  borderRadius: 20 * s,
                  padding: `${10 * s}px ${20 * s}px`,
                  color: primaryHighlight,
                  fontSize: 18 * s,
                  fontWeight: 600,
                  letterSpacing: "0.1em",
                  whiteSpace: "nowrap",
                  opacity: orbitReveal
                }}>
                  MAIN YOUTUBE CHANNEL
                </div>
              )}

              {/* 3D Depth Shadow */}
              <div style={{
                position: "absolute", width: "100%", height: "100%",
                backgroundColor: secondaryHighlight,
                borderRadius: 24 * s,
                transform: `translate(${8 * s}px, ${8 * s}px)`,
              }} />
              
              {/* Main Surface */}
              <div style={{
                position: "absolute", width: "100%", height: "100%",
                backgroundColor: surfaceColor,
                borderRadius: 24 * s,
                border: `2px solid rgba(0,0,0,0.05)`,
                overflow: "hidden",
                display: "flex", flexDirection: "column"
              }}>
                {/* Header Image Area */}
                <div style={{ height: 120 * s, background: `linear-gradient(135deg, ${primaryHighlight}, ${secondaryHighlight})`, position: "relative" }} />
                {/* Profile Row */}
                <div style={{ padding: 24 * s, display: "flex", alignItems: "center", gap: 16 * s }}>
                  <div style={{ width: 60 * s, height: 60 * s, borderRadius: "50%", backgroundColor: "#334155" }} />
                  <div style={{ flex: 1 }}>
                    <div style={{ width: 140 * s, height: 16 * s, backgroundColor: "#334155", borderRadius: 8 * s, marginBottom: 8 * s }} />
                    <div style={{ width: 90 * s, height: 12 * s, backgroundColor: "#94a3b8", borderRadius: 6 * s }} />
                  </div>
                  <div style={{ padding: `${8 * s}px ${16 * s}px`, backgroundColor: "#0f172a", color: surfaceColor, borderRadius: 20 * s, fontSize: 12 * s, fontWeight: 700 }}>
                    Subscribe
                  </div>
                </div>
                {/* Thumbnails Row */}
                <div style={{ padding: `0 ${24 * s}px`, display: "flex", gap: 12 * s, flex: 1 }}>
                  {[1, 2, 3, 4].map(i => (
                    <div key={i} style={{ flex: 1, backgroundColor: "#1e293b", borderRadius: 12 * s, height: 80 * s }} />
                  ))}
                </div>
              </div>
            </div>
          )}

          {/* SECOND CHANNEL CARD */}
          {frame >= T_PAN_RIGHT && (
            <div style={{
              position: "absolute",
              left: secondCoords.x,
              top: secondCoords.y,
              transform: `translate(-50%, -50%) scale(${secondEnter}) translateY(${secondDriftY}px)`,
              opacity: secondOpacity,
              width: 420 * s,
              height: 280 * s,
            }}>
              
              <div style={{
                position: "absolute",
                top: -60 * s,
                left: "50%",
                transform: "translateX(-50%)",
                backgroundColor: backgroundColor,
                border: `2px solid ${primaryHighlight}`,
                borderRadius: 20 * s,
                padding: `${8 * s}px ${16 * s}px`,
                color: primaryHighlight,
                fontSize: 14 * s,
                fontWeight: 600,
                letterSpacing: "0.1em",
                whiteSpace: "nowrap",
              }}>
                HIGH-TICKET BUYER CHANNEL
              </div>

              <div style={{
                position: "absolute", width: "100%", height: "100%",
                backgroundColor: secondaryHighlight,
                borderRadius: 20 * s,
                transform: `translate(${6 * s}px, ${6 * s}px)`,
              }} />
              
              <div style={{
                position: "absolute", width: "100%", height: "100%",
                backgroundColor: surfaceColor,
                borderRadius: 20 * s,
                border: `2px solid rgba(0,0,0,0.05)`,
                overflow: "hidden",
                display: "flex", flexDirection: "column"
              }}>
                <div style={{ height: 90 * s, background: `linear-gradient(135deg, ${secondaryHighlight}, ${primaryHighlight})`, position: "relative" }} />
                <div style={{ padding: 16 * s, display: "flex", alignItems: "center", gap: 12 * s }}>
                  <div style={{ width: 44 * s, height: 44 * s, borderRadius: "50%", backgroundColor: "#334155" }} />
                  <div style={{ flex: 1 }}>
                    <div style={{ width: 100 * s, height: 12 * s, backgroundColor: "#334155", borderRadius: 6 * s, marginBottom: 6 * s }} />
                    <div style={{ width: 60 * s, height: 10 * s, backgroundColor: "#94a3b8", borderRadius: 5 * s }} />
                  </div>
                </div>
                <div style={{ padding: `0 ${16 * s}px`, display: "flex", gap: 10 * s, flex: 1 }}>
                  {[1, 2, 3].map(i => (
                    <div key={i} style={{ flex: 1, backgroundColor: "#1e293b", borderRadius: 8 * s, height: 60 * s }} />
                  ))}
                </div>
              </div>
            </div>
          )}

          {/* SOCIAL ICONS */}
          {frame >= T_ZOOM_OUT && (
            <>
              {/* LinkedIn */}
              <div style={{
                position: "absolute", left: linkedinCoords.x, top: linkedinCoords.y,
                transform: `translate(-50%, -50%) scale(${socialIn1 * socialReduceScale}) translateY(${Math.sin(frame/40)*5*s}px)`,
                opacity: socialOpacity,
                width: 100 * s, height: 100 * s,
              }}>
                <div style={{ position: "absolute", width: "100%", height: "100%", backgroundColor: secondaryHighlight, borderRadius: 24 * s, transform: `translate(4px, 4px)` }} />
                <div style={{ position: "absolute", width: "100%", height: "100%", backgroundColor: "#0a66c2", borderRadius: 24 * s, border: `3px solid ${surfaceColor}`, display: "flex", alignItems: "center", justifyContent: "center" }}>
                   <div style={{ color: surfaceColor, fontSize: 50 * s, fontWeight: 900, fontFamily: "sans-serif", marginLeft: 4 * s }}>in</div>
                </div>
              </div>

              {/* Instagram */}
              <div style={{
                position: "absolute", left: igCoords.x, top: igCoords.y,
                transform: `translate(-50%, -50%) scale(${socialIn2 * socialReduceScale}) translateY(${Math.cos(frame/45)*5*s}px)`,
                opacity: socialOpacity,
                width: 110 * s, height: 110 * s,
              }}>
                <div style={{ position: "absolute", width: "100%", height: "100%", backgroundColor: secondaryHighlight, borderRadius: 28 * s, transform: `translate(4px, 4px)` }} />
                <div style={{ 
                  position: "absolute", width: "100%", height: "100%", 
                  background: "linear-gradient(45deg, #f09433 0%, #e6683c 25%, #dc2743 50%, #cc2366 75%, #bc1888 100%)", 
                  borderRadius: 28 * s, border: `3px solid ${surfaceColor}`, display: "flex", alignItems: "center", justifyContent: "center" 
                }}>
                   <svg width={60 * s} height={60 * s} viewBox="0 0 24 24" fill="none" stroke={surfaceColor} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                     <rect x="2" y="2" width="20" height="20" rx="5" ry="5"></rect>
                     <path d="M16 11.37A4 4 0 1 1 12.63 8 4 4 0 0 1 16 11.37z"></path>
                     <line x1="17.5" y1="6.5" x2="17.51" y2="6.5"></line>
                   </svg>
                </div>
                
                {/* Calendar Label Below IG */}
                <div style={{
                  position: "absolute",
                  top: 130 * s,
                  left: "50%",
                  transform: "translateX(-50%)",
                  display: "flex", flexDirection: "column", alignItems: "center",
                  gap: 8 * s
                }}>
                  <svg width={32 * s} height={32 * s} viewBox="0 0 24 24" fill="none" stroke={primaryHighlight} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <rect x="3" y="4" width="18" height="18" rx="2" ry="2"></rect>
                    <line x1="16" y1="2" x2="16" y2="6"></line>
                    <line x1="8" y1="2" x2="8" y2="6"></line>
                    <line x1="3" y1="10" x2="21" y2="10"></line>
                    <circle cx="9" cy="15" r="1"></circle>
                    <circle cx="15" cy="15" r="1"></circle>
                  </svg>
                  <div style={{ color: primaryHighlight, fontSize: 16 * s, fontWeight: 700, letterSpacing: "0.1em", whiteSpace: "nowrap" }}>
                    POSTING DAILY
                  </div>
                </div>
              </div>

              {/* TikTok */}
              <div style={{
                position: "absolute", left: tiktokCoords.x, top: tiktokCoords.y,
                transform: `translate(-50%, -50%) scale(${socialIn3 * socialReduceScale}) translateY(${Math.sin((frame+20)/40)*5*s}px)`,
                opacity: socialOpacity,
                width: 100 * s, height: 100 * s,
              }}>
                <div style={{ position: "absolute", width: "100%", height: "100%", backgroundColor: secondaryHighlight, borderRadius: 24 * s, transform: `translate(4px, 4px)` }} />
                <div style={{ position: "absolute", width: "100%", height: "100%", backgroundColor: "#000000", borderRadius: 24 * s, border: `3px solid ${surfaceColor}`, display: "flex", alignItems: "center", justifyContent: "center" }}>
                   <svg width={50 * s} height={50 * s} viewBox="0 0 24 24" fill={surfaceColor}>
                     <path d="M12.525.02c1.31-.02 2.61-.01 3.91-.02.08 1.53.63 3.09 1.75 4.17 1.12 1.11 2.7 1.62 4.24 1.79v4.03c-1.44-.05-2.89-.35-4.2-.97-.57-.26-1.1-.59-1.62-.93v7.2c0 1.63-.56 3.26-1.6 4.47-1.15 1.34-2.88 2.1-4.66 2.16-1.93.07-3.92-.47-5.38-1.78-1.55-1.37-2.45-3.37-2.42-5.45.03-2.02.9-3.96 2.37-5.37 1.48-1.44 3.52-2.22 5.57-2.14.04 1.37.01 2.75.03 4.13-1.04-.15-2.14.04-3 .67-.8.59-1.28 1.54-1.28 2.54-.01 1.05.5 2.05 1.31 2.63.81.58 1.86.76 2.82.53 1.05-.25 1.94-1.01 2.3-2.03.14-.4.22-.83.21-1.26v-14.4h3.65z"/>
                   </svg>
                </div>
              </div>
            </>
          )}

        </AbsoluteFill>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default EcosystemSequence;